package GeneratedModel {
  private import ScalarValues::*;
  part def Controller {
    in attribute io_0 : Real;
    in attribute io_1 : Boolean;
    in attribute io_2 : Integer;
    in attribute io_2_valid : Boolean;
    attribute targetCm : Integer := 400;
    attribute lastDistanceCm : Integer := 0;
    perform action tick {
      first start;
      then if io_2_valid {
        first start;
        then assign targetCm := io_2;
      }
      then if io_1 {
        first start;
        then assign lastDistanceCm := RealFunctions::floor(io_0);
      }
    }
    out attribute serial_0_trigger : Boolean = (if and=[io_1, io_2_valid] ? true else false);
    out attribute serial_0_value_0 : Integer = (if lastDistanceCm > targetCm ? 0 else (if lastDistanceCm == targetCm ? 0 else 0));
  }
  part system : Controller;
}

